-- ============================================================
-- 34. Playground 表单模板表 (hp_playground_templates)
-- ============================================================
--
-- 初始 21 条模板的完整数据固化在本脚本中（迁移自原 JSON 数据文件，现已删除），按原顺序落 sort_order。
-- fields 为表单 schema 的 JSON 原文，内含 $t: / $handler: 引用，必须整列保存、不可拆解。
-- 注意：运行时 CRUD 以本表为唯一真源；本脚本会 DROP 重建并覆盖为初始快照，
--       库中后续新增/编辑的模板会丢失，仅用于初始化或明确要重置时执行。
-- ============================================================
SET NAMES utf8mb4;

DROP TABLE IF EXISTS `hp_playground_templates`;
CREATE TABLE `hp_playground_templates` (
  `id`          VARCHAR(64)  NOT NULL COMMENT '模板唯一标识（如 config-weather）',
  `label`       VARCHAR(191) NOT NULL COMMENT '展示名称（支持 $t: i18n 键）',
  `category`    VARCHAR(64)  NULL COMMENT '分组',
  `fields`      JSON         NOT NULL COMMENT '表单 schema 数组（JSON 原文）',
  `sort_order`  INT UNSIGNED NOT NULL DEFAULT 0 COMMENT '展示顺序（与原 JSON 数组一致）',
  `created_at`  DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at`  DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_category` (`category`),
  KEY `idx_sort_order` (`sort_order`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Playground 表单模板配置';

INSERT INTO `hp_playground_templates` (`id`, `label`, `category`, `fields`, `sort_order`) VALUES
  ('config-weather', '$t:playground.schema.tplLabelWeather', 'config', '[{\"name\":\"JUHE_WEATHER_KEY\",\"label\":\"$t:playground.schema.weatherApiKeyLabel\",\"type\":\"input\",\"placeholder\":\"$t:playground.schema.weatherApiKeyPlaceholder\",\"clearable\":true,\"inputType\":\"$handler:config.passwordToggle\",\"rules\":[{\"required\":true,\"message\":\"$t:playground.schema.weatherApiKeyRequired\"}]},{\"name\":\"_selectedProvince\",\"label\":\"$t:playground.schema.weatherCityLabel\",\"type\":\"group\",\"rules\":[{\"required\":true,\"message\":\"$t:playground.schema.weatherCityRequired\"}],\"children\":[{\"name\":\"_selectedProvince\",\"type\":\"select\",\"placeholder\":\"$t:playground.schema.weatherProvincePlaceholder\",\"clearable\":true,\"width\":\"160px\",\"options\":\"$handler:config.provinceOptions\",\"onChange\":\"$handler:config.onProvinceChange\"},{\"name\":\"WEATHER_CITY_NAME\",\"type\":\"select\",\"placeholder\":\"$t:playground.schema.weatherCityPlaceholder\",\"clearable\":true,\"disabled\":\"$handler:config.cityDisabled\",\"options\":\"$handler:config.cityOptions\"}]}]', 1) ,
